source /root/lab/lib.sh
exec > >(tee $LOGS/t8-restic-logical.log) 2>&1
systemctl start exponetdb-node-helper.socket
RD=/etc/exponetdb-node/repositories/$RESTIC; RR=/var/lib/restic-repo
rm -rf $RR; install -d -m0700 -o postgres -g postgres $RR; install -d -m0755 $RD
RPW=$(openssl rand -hex 16); printf '%s' "$RPW" > $RD/password; chmod 0600 $RD/password; echo "$RR" > $RD/repository; echo owned > $RD/mode; chmod 0644 $RD/mode $RD/repository
install -m0600 -o postgres -g postgres $RD/password /var/lib/c35/restic.pw
runuser -u postgres -- restic init --no-cache --repo $RR --password-file /var/lib/c35/restic.pw | tail -1
echo "=== logical run (pg_dump of app + globals) through backup.run@1"
psqlx "CREATE ROLE appowner NOLOGIN; CREATE ROLE reader LOGIN; GRANT SELECT ON ALL TABLES IN SCHEMA public TO reader" >/dev/null 2>&1 || true
ROWS=$(psqlx "SELECT count(*) FROM accounts"); echo "source accounts=$ROWS"
R=$(rid); T0=$(ts); c backup.run "{\"cluster\":$CLUSTER,\"repository\":$RESTICJ,\"runId\":\"$R\",\"kind\":\"logical\",\"databases\":[\"app\"]}" | jq -c '.error // .result|{runId}'
echo "-- unit while running (EnvironmentFile, props):"; systemctl show exponetdb-run-$R.service -p ActiveState,EnvironmentFiles,User,ProtectSystem,ReadWritePaths 2>&1 | tr '\n' ' '; echo
out=$(wait_run $R 900); echo "logical: state=$(echo "$out"|jq -r .result.state) label=$(echo "$out"|jq -r .result.outcome.label) duration=$(echo "$(ts) - $T0"|bc)s"
SNAP=$(echo "$out"|jq -r .result.outcome.label); echo "$out" | jq -r .result.excerpt | tail -4 | cut -c1-200
ls -la /var/lib/exponetdb-node-engine/runs/$R /var/lib/exponetdb-node-engine/runs/$R/work 2>&1 | head -12
echo "secrets in run record/result/excerpt? $(grep -rl "$RPW" /var/lib/exponetdb-node-engine/runs/$R 2>/dev/null | wc -l) files; in journal: $(journalctl --no-pager -o cat 2>/dev/null | grep -c "$RPW")"
echo "-- backup.list restic"; c backup.list "{\"cluster\":$CLUSTER,\"repository\":$RESTICJ}" | jq -c '.result|{engineVersion,stanza,backups:[.backups[]|{label:.label[0:12],kind,sizeBytes}]}'
echo "-- verify whole repo / snapshot-scoped"
R2=$(rid); c backup.verify "{\"cluster\":$CLUSTER,\"repository\":$RESTICJ,\"runId\":\"$R2\",\"label\":null,\"snapshot\":null}" >/dev/null; wait_run $R2 300 | jq -c '.result|{state,verifyErrors:.outcome.verifyErrors}'
echo "snapshot-scoped: $(c backup.verify "{\"cluster\":$CLUSTER,\"repository\":$RESTICJ,\"runId\":\"$(rid)\",\"label\":null,\"snapshot\":\"$SNAP\"}" | jq -c '.error // .result')"
echo "=== the runbook's restic variant (generated by the product's generateRunbook)"
cd /root/exdb/apps/server && bun -e "
import { generateRunbook } from '@exponetdb/backups'
import { writeFileSync } from 'node:fs'
const r = generateRunbook({ repositoryId: 'bkr_01M70000000000000000000002', revision: 1, clusterId: 'cls_01M70000000000000000000009', engine: 'restic', provider: 'posix', endpointHost: null, region: null, bucket: null, prefix: 'var/lib/restic-repo', stanza: null, repoIndex: null, cipher: 'restic', pinnedEngineVersion: null, postgresMajor: 17 })
writeFileSync('/var/lib/c35/recover-restic.sh', r.script, { mode: 0o755 }); console.log(r.digest, r.placeholders.map((p) => p.name).join(','))
"
cd /
RB() { runuser -u postgres -- env TARGET_DIR=$1 PG_BIN=/usr/lib/postgresql/17/bin PORT=${PORT:-55442} RESTIC_PASSWORD_FILE=${PASSF:-/var/lib/c35/restic.pw} ${SNAPSHOT:+SNAPSHOT=$SNAPSHOT} sh /var/lib/c35/recover-restic.sh; }
T0=$(ts); RB /var/lib/c35/restic-restore 2>&1 | tail -12 | cut -c1-220; echo "rc=${PIPESTATUS[0]} duration=$(echo "$(ts) - $T0"|bc)s"
SOCK=/var/lib/c35/restic-restore.exponetdb/socket
echo "-- restored: $(runuser -u postgres -- psql -X -A -t -h $SOCK -p 55442 -d app -c 'SELECT count(*) FROM accounts') accounts (source $ROWS); big=$(runuser -u postgres -- psql -X -A -t -h $SOCK -p 55442 -d app -c 'SELECT count(*) FROM big')"
echo "-- roles in restored cluster (globals applied?): $(runuser -u postgres -- psql -X -A -t -h $SOCK -p 55442 -d postgres -c "SELECT string_agg(rolname, ',' ORDER BY rolname) FROM pg_roles WHERE rolname !~ '^pg_'")"
echo "-- globals.sql in snapshot: $(runuser -u postgres -- restic restore latest --no-cache --repo $RR --password-file /var/lib/c35/restic.pw --target /var/lib/c35/peek --include '*globals.sql' >/dev/null 2>&1; find /var/lib/c35/peek -name 'globals*' | head -2)"
runuser -u postgres -- /usr/lib/postgresql/17/bin/pg_ctl -D /var/lib/c35/restic-restore stop -m fast 2>&1 | tail -1
echo "=== missing globals file: a snapshot with the dump but no globals.sql"
runuser -u postgres -- sh -c 'rm -rf /var/lib/c35/noglobals && mkdir -p /var/lib/c35/noglobals && cp $(find /var/lib/c35/peek -name "app.dump" | head -1 || true) /var/lib/c35/noglobals/ 2>/dev/null; true'
runuser -u postgres -- restic restore latest --no-cache --repo $RR --password-file /var/lib/c35/restic.pw --target /var/lib/c35/peek --include '*app.dump' >/dev/null 2>&1
DUMP=$(find /var/lib/c35/peek -name app.dump | head -1); echo "dump file: $DUMP"
runuser -u postgres -- sh -c "cp $DUMP /var/lib/c35/noglobals/app.dump && restic backup --no-cache --repo $RR --password-file /var/lib/c35/restic.pw --tag exponetdb /var/lib/c35/noglobals" | tail -2
NOG=$(runuser -u postgres -- restic snapshots --no-cache --repo $RR --password-file /var/lib/c35/restic.pw --json | jq -r '.[-1].id')
SNAPSHOT=$NOG PORT=55443 RB /var/lib/c35/restic-noglobals 2>&1 | tail -6 | cut -c1-220; echo "rc=${PIPESTATUS[0]} (expected by M-5: the runbook stops on a missing globals file)"
runuser -u postgres -- /usr/lib/postgresql/17/bin/pg_ctl -D /var/lib/c35/restic-noglobals stop -m fast 2>&1 | tail -1
echo "=== restore role: as root (over-privileged) and as nobody (under-privileged)"
PORT=55444 TARGET=/var/lib/c35/restic-root; env TARGET_DIR=$TARGET PG_BIN=/usr/lib/postgresql/17/bin PORT=55444 RESTIC_PASSWORD_FILE=/var/lib/c35/restic.pw sh /var/lib/c35/recover-restic.sh 2>&1 | tail -3 | cut -c1-220; echo "rc=${PIPESTATUS[0]} as root"
runuser -u nobody -- env TARGET_DIR=/var/lib/c35/restic-nobody PG_BIN=/usr/lib/postgresql/17/bin RESTIC_PASSWORD_FILE=/var/lib/c35/restic.pw sh /var/lib/c35/recover-restic.sh 2>&1 | tail -3 | cut -c1-220; echo "rc=${PIPESTATUS[0]} as nobody"
echo "=== wrong restic password"; printf wrong > /var/lib/c35/badrestic; chown postgres: /var/lib/c35/badrestic
PASSF=/var/lib/c35/badrestic PORT=55445 RB /var/lib/c35/restic-badpw 2>&1 | tail -3 | cut -c1-200; echo "rc=${PIPESTATUS[0]}"
echo "=== cleanup check"; ls /var/lib/c35; pgrep -fa "postgres -D /var/lib/c35" | cut -c1-120
